-- CMV — Embalagem composta por Nota Fiscal (travada) + produtos_master(setor='EMBALAGENS').
-- Corrige o modelo do item de embalagem do construtor de CMV:
--   ANTES: item de embalagem apontava para `insumos` (só matéria-prima/ingredientes — não há
--          embalagens cadastradas lá).
--   AGORA: embalagem = linha de `produtos_master` com setor='EMBALAGENS' (112 ativas), com custo
--          COMPOSTO por uma NF específica TRAVADA (itens_nota_fiscal), campo de unidades por
--          embalagem (pacote→unidade) e fallback de VALOR FIXO manual quando não há NF.
--
-- Reescreve public.cmv_compute_item_cost com nova prioridade, mantendo retrocompatibilidade
-- total com os itens já existentes (que só têm insumo_id e/ou preco_unitario_esboco).
-- Recompute permanece a cargo do trigger cmv_item_recompute_trg já existente (dispara em
-- qualquer UPDATE da linha de cmv_itens — sem cláusula OF —, logo cobre as novas colunas).
-- Fonte de verdade do custo: public.cmv_compute_item_cost / public.recompute_cmv_cost.
-- ADR: .harness/memory-bank/decisions/ADR-20260616-cmv-embalagem-nf.md

-- ============================================================
-- 1. NOVAS COLUNAS em cmv_itens (todas NULL — itens existentes inalterados)
-- ============================================================
-- FK bigint → PK int4 (produtos_master.id / itens_nota_fiscal.id são integer):
-- válido em Postgres (int4/int8 compartilham operator class btree); espelha o
-- padrão já em produção de cmv_itens.insumo_id (bigint) → insumos.id.
ALTER TABLE public.cmv_itens
  ADD COLUMN IF NOT EXISTS produto_master_id      bigint  REFERENCES public.produtos_master(id)   ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS nf_item_id             bigint  REFERENCES public.itens_nota_fiscal(id)  ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS unidades_por_embalagem numeric;

-- ============================================================
-- 2. ÍNDICES nas novas FKs (tabela pequena; CREATE INDEX simples — sem CONCURRENTLY
--    para permitir rodar dentro da transação da migration)
-- ============================================================
CREATE INDEX IF NOT EXISTS cmv_itens_produto_master_id_idx ON public.cmv_itens(produto_master_id);
CREATE INDEX IF NOT EXISTS cmv_itens_nf_item_id_idx        ON public.cmv_itens(nf_item_id);

-- ============================================================
-- 3. REESCRITA de cmv_compute_item_cost — nova prioridade de fonte de custo
--    Ordem: NF travada  >  insumo (legado)  >  produto_master  >  esboço (valor fixo)
-- ============================================================
CREATE OR REPLACE FUNCTION public.cmv_compute_item_cost(p_item_id bigint)
RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_item        RECORD;
  v_insumo      RECORD;
  v_cost        numeric := 0;
  v_ratio       numeric := 1.0;
  v_uf          text;     -- unidade do item (lower)
  v_ui          text;     -- unidade de compra do insumo (lower)
  v_nf_valor    numeric;  -- valor_unitario da NF travada
  v_unidades    numeric;  -- unidades por embalagem (pacote→unidade)
  v_unit        numeric;  -- custo por unidade derivado
  v_pm_custo    numeric;  -- preco_custo do produto_master (já por unidade)
BEGIN
  SELECT * INTO v_item FROM cmv_itens WHERE id = p_item_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- 1) NF TRAVADA (prioridade máxima): custo composto pela NF escolhida, NÃO auto-latest.
  --    custo_por_unidade = valor_unitario_NF / unidades_por_embalagem (default 1).
  IF v_item.nf_item_id IS NOT NULL THEN
    SELECT valor_unitario INTO v_nf_valor
      FROM itens_nota_fiscal
     WHERE id = v_item.nf_item_id;
    IF FOUND AND coalesce(v_nf_valor, 0) > 0 THEN
      -- NULL ou 0 em unidades_por_embalagem → 1 (pacote = 1 unidade).
      v_unidades := NULLIF(coalesce(v_item.unidades_por_embalagem, 1), 0);
      IF v_unidades IS NULL THEN v_unidades := 1; END IF;
      v_unit := v_nf_valor / v_unidades;
      v_cost := v_unit * coalesce(v_item.quantidade, 0);
      RETURN coalesce(v_cost, 0);
    END IF;
  END IF;

  -- 2) INSUMO real (legado) — preço de compra com conversão auto entre unidades standard.
  IF v_item.insumo_id IS NOT NULL THEN
    SELECT preco_custo, unidade_compra, fator_conversao
      INTO v_insumo
      FROM insumos WHERE id = v_item.insumo_id;
    IF FOUND AND v_insumo.preco_custo IS NOT NULL THEN
      v_uf := lower(coalesce(v_item.unidade, ''));
      v_ui := lower(coalesce(v_insumo.unidade_compra, ''));

      IF    v_uf = v_ui THEN                       v_ratio := 1.0;
      ELSIF v_uf = 'g'  AND v_ui = 'kg' THEN       v_ratio := 0.001;
      ELSIF v_uf = 'kg' AND v_ui = 'g'  THEN       v_ratio := 1000;
      ELSIF v_uf = 'ml' AND v_ui = 'l'  THEN       v_ratio := 0.001;
      ELSIF v_uf = 'l'  AND v_ui = 'ml' THEN       v_ratio := 1000;
      ELSIF v_uf = 'mg' AND v_ui = 'g'  THEN       v_ratio := 0.001;
      ELSIF v_uf = 'g'  AND v_ui = 'mg' THEN       v_ratio := 1000;
      ELSE
        -- Unidades não-standard (pack, un, pote, cx): fator_conversao manual.
        IF v_insumo.fator_conversao IS NOT NULL AND v_insumo.fator_conversao > 0 THEN
          v_ratio := 1.0 / v_insumo.fator_conversao;
        ELSE
          v_ratio := 1.0;
        END IF;
      END IF;

      v_cost := v_insumo.preco_custo * coalesce(v_item.quantidade, 0) * v_ratio;
    END IF;
  END IF;

  -- 3) PRODUTO_MASTER (embalagem do setor EMBALAGENS sem NF travada).
  --    preco_custo já é por unidade.
  IF v_cost = 0 AND v_item.produto_master_id IS NOT NULL THEN
    SELECT preco_custo INTO v_pm_custo
      FROM produtos_master WHERE id = v_item.produto_master_id;
    IF coalesce(v_pm_custo, 0) > 0 THEN
      v_cost := v_pm_custo * coalesce(v_item.quantidade, 0);
    END IF;
  END IF;

  -- 4) FALLBACK: esboço / valor fixo manual (preço livre no item).
  IF v_cost = 0 AND v_item.preco_unitario_esboco IS NOT NULL THEN
    v_cost := v_item.preco_unitario_esboco * coalesce(v_item.quantidade, 0);
  END IF;

  RETURN coalesce(v_cost, 0);
END;
$function$;

-- ============================================================
-- 4. Backfill defensivo — recomputa todas as CMVs existentes para garantir consistência
--    da custo_calculado após a redefinição da função (idempotente; itens existentes
--    permanecem com o MESMO custo, pois não têm as novas colunas).
-- ============================================================
DO $$
DECLARE
  v_cmv_id bigint;
BEGIN
  FOR v_cmv_id IN SELECT id FROM public.cmv_fichas LOOP
    PERFORM public.recompute_cmv_cost(v_cmv_id);
  END LOOP;
END $$;

-- ============================================================
-- RLS: nenhuma mudança necessária. As novas colunas pertencem à própria linha de
-- cmv_itens, já coberta pela policy auth_all_cmv_itens (FOR ALL TO authenticated
-- USING(true) WITH CHECK(true)). produtos_master e itens_nota_fiscal já têm suas
-- próprias policies; cmv_compute_item_cost roda SECURITY DEFINER e lê ambas com
-- search_path travado em 'public'.
-- ============================================================

-- ============================================================
-- DOWN (referência):
--   -- Restaurar a versão anterior da função (sem NF/produto_master):
--   --   ver supabase/migrations/20260612160000_cmv_fichas_itens.sql §3
--   DROP INDEX IF EXISTS public.cmv_itens_nf_item_id_idx;
--   DROP INDEX IF EXISTS public.cmv_itens_produto_master_id_idx;
--   ALTER TABLE public.cmv_itens
--     DROP COLUMN IF EXISTS unidades_por_embalagem,
--     DROP COLUMN IF EXISTS nf_item_id,
--     DROP COLUMN IF EXISTS produto_master_id;
-- ============================================================

