// --- Components Styles ---
const GlassCard = ({ children, className }: { children: React.ReactNode; className?: string }) => (
  <div className={cn("relative overflow-hidden rounded-2xl bg-white/40 dark:bg-black/20 backdrop-blur-md border border-white/20 dark:border-white/10 shadow-sm transition-all hover:shadow-md", className)}>
    <div className="absolute inset-0 bg-gradient-to-br from-white/20 via-transparent to-transparent pointer-events-none" />
    <div className="relative z-10">{children}</div>
  </div>
);

const KPICard = ({ title, value, subtext, icon: Icon, trend }: { title: string; value: string | number; subtext: string; icon: any; trend?: "up" | "down" | "neutral" }) => (
  <GlassCard className="p-5 flex items-center justify-between">
    <div>
      <p className="text-sm font-medium text-muted-foreground uppercase tracking-wider text-[10px]">{title}</p>
      <h3 className="text-2xl font-bold mt-1 text-[#57715B] dark:text-[#E6DCCF]">{value}</h3>
      <p className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
        {trend === "up" && <TrendingUp className="h-3 w-3 text-green-500" />}
        {trend === "down" && <TrendingUp className="h-3 w-3 text-red-500 rotate-180" />}
        {subtext}
      </p>
    </div>
    <div className="h-10 w-10 rounded-full bg-[#57715B]/10 dark:bg-white/5 flex items-center justify-center">
      <Icon className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
    </div>
  </GlassCard>
);

interface ProductionEntry {
  id: string;
  product_name: string;
  quantity: number;
}

interface HistoryEntry {
  id: string;
  date: string;
  product_name: string;
  quantity: number;
  created_at: string;
  created_by?: string | null;
}

interface ProductStats {
  name: string;
  total: number;
  avgDaily: number;
  maxDaily: number;
  frequency: number; // % of days with production
  volatility: number; // standard deviation
  share: number; // % of total production
  dates: string[];
}

interface AnalyticsData {
  totalProduction: number;
  momGrowth: number; // Month over Month (or Period over Period) growth %
  efficiency: number; // avg items per production hour (simple proxy)
  activeDays: number;
  topProducts: ProductStats[];
  products: ProductStats[];
  dailyTrend: Array<{ date: string; total: number; previousTotal?: number }>;
  monthlyTrend: Array<{ month: string; total: number }>;
  hourlyDistribution: Array<{ hour: number; count: number }>;
  dayOfWeekAnalysis: Array<{ day: string; avg: number; total: number }>;
  rawEntries: HistoryEntry[];
  previousRawEntries: HistoryEntry[];
}

function formatDateISO(d: Date) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function parseISODateLocal(iso: string) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(y, (m || 1) - 1, d || 1);
}

function formatDateBR(iso: string) {
  try {
    const [y, m, d] = iso.split("-");
    return `${d}/${m}/${y}`;
  } catch {
    return iso;
  }
}

function formatMonthBR(ym: string) {
  try {
    const [y, m] = ym.split("-").map(Number);
    const dt = new Date(y, (m || 1) - 1, 1);
    return dt.toLocaleDateString("pt-BR", { month: "short", year: "2-digit" });
  } catch {
    return ym;
  }
}

