        setVoiceStatus("👂 Detectando sua voz...");
      };

      recognition.onresult = (event: any) => {
        let finalText = '';
        let interim = '';
        for (let i = 0; i < event.results.length; i++) {
          const t = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalText += t;
          } else {
            interim += t;
          }
        }

        if (interim) {
