      };

      recognition.onspeechend = () => {
        setVoiceStatus("⏸️ Pausa detectada, aguardando mais fala...");
      };

      recognition.onerror = (event: any) => {
        wideWarn('producao.voice_error', `Erro de reconhecimento de voz: ${event.error}`, { domain: 'producao', attributes: { error: event.error } });

        if (event.error === 'network') {
          // Detectar Brave Browser
          const isBrave = (navigator as any).brave !== undefined;

          if (retryCount < maxRetries) {
            retryCount++;
            setVoiceStatus(`⚠️ Erro de conexão. Tentativa ${retryCount}/${maxRetries}...`);
            setTimeout(() => {
              if (recognitionRef.current && !recognitionRef.current.manualStop) {
                startRecognition();
              }
            }, 1000);
            return;
          } else {
            if (isBrave) {
              setVoiceStatus("❌ BRAVE BROWSER: Clique no leão 🦁 na barra de endereço → Desative 'Shields' → Recarregue a página");
            } else {
              setVoiceStatus("❌ Serviço de voz do Google indisponível. Tente Chrome ou Edge.");
            }
            setIsListening(false);
            if (recognitionRef.current) recognitionRef.current.manualStop = true;
            return;
          }
        }

        if (event.error === 'not-allowed') {
          setVoiceStatus("❌ Microfone bloqueado! Clique no 🔒 na barra de endereço e permita.");
          setIsListening(false);
          if (recognitionRef.current) recognitionRef.current.manualStop = true;
          return;
        }

        if (event.error === 'audio-capture') {
          setVoiceStatus("❌ Microfone não encontrado. Conecte um microfone.");
          setIsListening(false);
          if (recognitionRef.current) recognitionRef.current.manualStop = true;
          return;
        }

        if (event.error === 'no-speech') {
          setVoiceStatus("🔇 Nenhum som detectado. Fale mais alto ou aproxime-se do microfone.");
        }
      };

      recognition.onend = () => {
        if (recognitionRef.current && !recognitionRef.current.manualStop) {
          setVoiceStatus("🔄 Reiniciando escuta...");
          setTimeout(() => {
            if (recognitionRef.current && !recognitionRef.current.manualStop) {
