  const matchAiItemsToDb = (items: Array<{ name: string; quantity: number }>) => {
    const suggestionsFor = (name: string) => {
      const scored = dbProducts.map(p => ({
        id: p.id,
        nome: p.nome,
        score: similarity(name, p.nome)
      })).sort((a, b) => b.score - a.score).slice(0, 5);
      return scored;
    };

    const mapped = items.map(item => {
      const sugg = suggestionsFor(item.name);
      const best = sugg[0];
      const threshold = 0.72;
      const isGood = best && best.score >= threshold;
      return {
        originalName: item.name,
        quantity: item.quantity,
        matchedName: isGood ? best.nome : undefined,
        matchedId: isGood ? best.id : undefined,
