          let matchedId = masterMap[cleanEntryName] || null;

          // Very basic fuzzy fallback just in case
          if (!matchedId) {
            const possibleKeys = Object.keys(masterMap);
            for (const k of possibleKeys) {
              if (k.includes(cleanEntryName) || cleanEntryName.includes(k)) {
                matchedId = masterMap[k];
                break;
              }
            }
          }

          return {
            date: selectedDate,
            product_name: entry.product_name,
            quantity: entry.quantity,
            produto_master_id: matchedId,
            created_by: user.id,
          };
        });

        const { error } = await supabase
          .from('daily_production')
          .insert(payload);

        if (error) throw error;
      }, telemetryAttrs);

      const durationMs = Math.round(performance.now() - startTime);
      const totalQuantity = productionEntries.reduce((sum, e) => sum + e.quantity, 0);

      wideInfo('producao.diaria.registrada', 'Produção diária registrada com sucesso', {
        attributes: {
          'producao.quantidade_produtos': productionEntries.length,
          'producao.quantidade_total': totalQuantity,
          'producao.data': selectedDate,
          'duration_ms': durationMs,
        },
      });
      recordProductionRecord({ 'producao.data': selectedDate });
      recordOperationDuration('producao.diaria', durationMs);

      toast({
        title: "Produção registrada com sucesso!",
        description: `${productionEntries.length} produtos salvos para ${formatDateBR(selectedDate)}`,
        duration: 3000
      });

      // Limpar formulário
      setProductionEntries([]);
      setSearchTerm("");
      setIsDateModalOpen(false);

    } catch (error) {
      const durationMs = Math.round(performance.now() - startTime);
      wideError('producao.diaria.erro', 'Falha ao registrar produção diária', {
        attributes: {
          'error.message': error instanceof Error ? error.message : String(error),
          'duration_ms': durationMs,
        },
      });
      recordError('producao_diaria', 'registrar');
      handleError(error, { domain: 'producao', operation: 'registerProduction', showToast: false });
      toast({ title: 'Erro ao registrar produção', variant: 'destructive' });
    } finally {
      setIsLoading(false);
    }
  };

  // MIA action hook — wired after handleSubmit is defined
  useMiaProducaoDiariaActions({
    setActiveTab,
    setDate,
    setSearchTerm,
    setIsAddModalOpen,
    setIsImportModalOpen,
    handleSubmit,
    setHistoryFilter,
    setAnalyticsPreset: applyAnalyticsPreset,
    setAnalyticsViewMode,
    setIsManageModalOpen,
    productionEntries,
  });

  // Função para registrar novo produto no banco
  const registerNewProduct = async () => {
    if (!newProductName.trim()) {
      toast({ title: "Nome do produto é obrigatório", variant: "destructive" });
      return;
    }

    // Registro global de produto (sem loja)

    setIsCreatingProduct(true);

    try {
      const productData = {
        loja_id: null,
        name: newProductName.trim(),
        active: true,
        created_by: user?.id || null,
      };

      const { error } = await supabase
        .from('daily_production_products')
        .insert(productData);

      if (error) throw error;

      toast({
        title: "Produto registrado com sucesso!",
        description: `${newProductName} foi adicionado à lista de produtos`,
        duration: 3000
      });

      // Limpar modal
      setNewProductName("");
      setIsNewProductModalOpen(false);

      // Recarregar lista de produtos (padrões + adicionados − excluídos)
      try {
        const { data: additionsData } = await supabase
          .from('daily_production_products')
          .select('id, name, active');

        const { data: exclusionsData } = await supabase
          .from('daily_production_exclusions')
          .select('name');

        const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
        const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
        const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
        const finalList = Array.from(new Set([...activeAdditions, ...defaultsIncluded]));
        setAllProducts(finalList);

        if (isImportModalOpen) {
          const activeAdditionsForIA = (additionsData || []).filter((a: any) => a.active).map((a: any) => ({ id: a.id, nome: a.name }));
          const defaultsIncludedForIA = defaultsIncluded.map((product, index) => ({ id: -(index + 1), nome: product }));
          setDbProducts([...activeAdditionsForIA, ...defaultsIncludedForIA]);
        }
      } catch (err) {
        handleError(err, { domain: 'producao', operation: 'reloadProductionListAfterRegister', showToast: false });
      }

    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'registerProduct', showToast: false });
      const message = (error?.message || '').toLowerCase();
      if (error?.code === '23505' || message.includes('duplicate') || message.includes('unique')) {
        toast({
          title: 'Produto já existe',
          description: 'Já há um produto com este nome nesta loja.',
          variant: 'destructive'
        });
      } else {
        toast({
          title: 'Erro ao registrar produto',
          description: error?.message || 'Tente novamente mais tarde.',
          variant: 'destructive'
        });
      }
    } finally {
      setIsCreatingProduct(false);
    }
  };

  // Remover produto adicionado (custom) da lista de produção
  const removeDailyAddition = async (id: number) => {
    try {
      const { error } = await supabase
        .from('daily_production_products')
        .delete()
        .eq('id', id);
      if (error) throw error;

      toast({ title: 'Produto removido da lista de produção' });

      const { data: additionsData } = await supabase
        .from('daily_production_products')
        .select('id, name, active');
      setDailyAdditions(additionsData || []);
      const { data: exclusionsData } = await supabase
        .from('daily_production_exclusions')
        .select('name');
      const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
      const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
      const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
      setAllProducts(Array.from(new Set([...activeAdditions, ...defaultsIncluded])));
    } catch (error) {
      handleError(error, { domain: 'producao', operation: 'removeDailyProduct', showToast: false });
      toast({ title: 'Erro ao remover produto', variant: 'destructive' });
    }
  };

  // Incluir/ocultar produto padrão na lista de produção
  const setDefaultProductIncluded = async (name: string, included: boolean) => {
    try {
      if (included) {
        const { error } = await supabase
          .from('daily_production_exclusions')
          .delete()
          .eq('name', name);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('daily_production_exclusions')
          .insert({ loja_id: null, name, created_by: user?.id || null });
        if (error) throw error;
      }
      const { data: exclusionsData } = await supabase
        .from('daily_production_exclusions')
        .select('name');
      setDailyExclusions((exclusionsData || []).map((e: any) => e.name));
      const { data: additionsData } = await supabase
        .from('daily_production_products')
        .select('id, name, active');
      setDailyAdditions(additionsData || []);

      const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
      const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
      const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
      setAllProducts(Array.from(new Set([...activeAdditions, ...defaultsIncluded])));
    } catch (error) {
      handleError(error, { domain: 'producao', operation: 'updateDefaultProductExclusion', showToast: false });
      toast({ title: 'Erro ao atualizar lista', variant: 'destructive' });
    }
  };

  const toggleSelectForDeletion = (name: string) => {
    setSelectedForDeletion(prev => prev.includes(name) ? prev.filter(n => n !== name) : [...prev, name]);
  };

  const deleteSelectedProducts = async () => {
    if (selectedForDeletion.length === 0) return;
    setIsDeletingProducts(true);
    try {
      const additionsIndex = new Map(
        dailyAdditions.filter(a => a.active).map(a => [a.name, a.id])
      );

      const ops = selectedForDeletion.map(name => {
        const id = additionsIndex.get(name);
        return id ? removeDailyAddition(id) : setDefaultProductIncluded(name, false);
      });

      await Promise.all(ops);

      setSelectedForDeletion([]);
      setIsDeleteMode(false);
      toast({ title: 'Itens removidos da lista', description: `${ops.length} removidos` });
    } catch (e) {
      handleError(e, { domain: 'producao', operation: 'deleteSelectedProducts', showToast: false });
      toast({ title: 'Erro ao remover itens', variant: 'destructive' });
    } finally {
      setIsDeletingProducts(false);
    }
  };

  // Funções para histórico
  const loadHistory = async () => {
    try {
      const { data, error } = await supabase
        .from('daily_production')
        .select('*')
        .gte('date', dateRange.start)
        .lte('date', dateRange.end)
        .order('date', { ascending: false });

      if (error) throw error;
      setHistory(data || []);
    } catch (error) {
      handleError(error, { domain: 'producao', operation: 'loadHistory', showToast: false });
    }
  };

  const deleteHistoryEntry = async (id: string) => {
    try {
      const confirmed = window.confirm('Tem certeza que deseja deletar este lançamento de produção?');
      if (!confirmed) return;
      const { error } = await supabase
        .from('daily_production')
        .delete()
        .eq('id', id);
      if (error) throw error;
      toast({ title: 'Produção deletada', description: 'O lançamento foi removido com sucesso.' });
      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'deleteHistoryEntry', showToast: false });
      const msg = (error?.message || '').toLowerCase();
      if (msg.includes('permission') || msg.includes('rls')) {
        toast({ title: 'Sem permissão para deletar', description: 'Apenas quem lançou pode deletar este registro.', variant: 'destructive' });
      } else {
        toast({ title: 'Erro ao deletar', description: error?.message || 'Tente novamente mais tarde.', variant: 'destructive' });
      }
    }
  };

  const openEditModal = (entry: HistoryEntry) => {
    setEditingEntry(entry);
    setEditProduct(entry.product_name);
    setEditQuantity(entry.quantity.toString());
    setEditDate(entry.date);
    setIsEditMode(true);
  };

  const closeEditModal = () => {
    setIsEditMode(false);
    setEditingEntry(null);
    setEditProduct("");
    setEditQuantity("");
    setEditDate("");
  };

  const editHistoryEntry = async () => {
    if (!editingEntry || !editProduct || !editQuantity || !editDate) {
      toast({
        title: "Dados incompletos",
        description: "Preencha todos os campos",
        variant: "destructive"
