      return;
    }

    try {
      const { error } = await supabase
        .from('daily_production')
        .update({
          product_name: editProduct,
          quantity: parseFloat(editQuantity),
          date: editDate
        })
        .eq('id', editingEntry.id);

      if (error) throw error;

      toast({
        title: 'Produção atualizada',
        description: 'A produção foi editada com sucesso.'
      });

      closeEditModal();
      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'editProduction', showToast: false });
      const msg = (error?.message || '').toLowerCase();
      if (msg.includes('permission') || msg.includes('rls')) {
        toast({
          title: 'Sem permissão para editar',
          description: 'Apenas quem lançou pode editar este registro.',
          variant: 'destructive'
        });
      } else {
        toast({
          title: 'Erro ao editar',
          description: error?.message || 'Tente novamente mais tarde.',
          variant: 'destructive'
        });
      }
    }
  };

  // Estados para edição de DATA em lote
  const [isEditDateBatchModalOpen, setIsEditDateBatchModalOpen] = useState(false);
  const [batchOldDate, setBatchOldDate] = useState("");
  const [batchNewDate, setBatchNewDate] = useState("");

  const openBatchDateEdit = (date: string) => {
    setBatchOldDate(date);
    setBatchNewDate(date);
    setIsEditDateBatchModalOpen(true);
  };

  const updateProductionDate = async () => {
    if (!batchNewDate) {
      toast({ title: "Selecione uma nova data", variant: "destructive" });
      return;
    }

    try {
      // Atualiza todas as entradas daquele dia para a nova data
      const { error } = await supabase
        .from('daily_production')
        .update({ date: batchNewDate })
        .eq('date', batchOldDate);

      if (error) throw error;

      toast({
        title: "Data de produção atualizada",
        description: `Produção movida de ${formatDateBR(batchOldDate)} para ${formatDateBR(batchNewDate)}`
      });

      setIsEditDateBatchModalOpen(false);
      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'updateProductionDate', showToast: false });
      toast({
        title: 'Erro ao mover produção',
        description: error?.message || 'Verifique suas permissões.',
        variant: 'destructive'
      });
    }
  };

  const deleteProductionBatch = async (date: string) => {
    const confirmed = window.confirm(`ATENÇÃO: Isso apagará TODOS os itens lançados no dia ${formatDateBR(date)}. Tem certeza?`);
    if (!confirmed) return;

    try {
      const { error } = await supabase
        .from('daily_production')
        .delete()
        .eq('date', date);

      if (error) throw error;

      toast({
        title: "Produção do dia removida",
        description: `Todos os registros de ${formatDateBR(date)} foram apagados.`
      });

      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'deleteDayProduction', showToast: false });
      toast({
        title: 'Erro ao apagar produção',
        description: error?.message || 'Verifique suas permissões.',
        variant: 'destructive'
      });
    }
  };

  // Funções para analytics
  const loadAnalytics = async () => {
    try {
      // 1. Definir períodos
      const currentStart = parseISO(analyticsDateRange.start);
      const currentEnd = parseISO(analyticsDateRange.end);
      const daysDiff = differenceInDays(currentEnd, currentStart) + 1;

      const previousStart = subDays(currentStart, daysDiff);
